import{_ as e,o as r,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2019-02-20:: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-02-20:: Ceph Orchestration Meeting","date":"2019-02-20T00:00:00.000Z","updated":"2019-04-17T00:00:00.000Z","tags":["Ceph","Orchestration","SSH Orchestrator","CLI","DeepSea"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-02-20_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-02-20_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),i={name:"posts/2019/2019-02-20_-_-_Ceph_Orchestration_Meeting.md"};function a(l,t,p,n,_,c){return r(),o("div",null,[...t[0]||(t[0]=[s("<p>本次会议主要讨论了Ceph存储系统中的SSH Orchestrator相关问题及其进展。以下是会议的关键细节和主要议题：</p><ol><li><p><strong>SSH Orchestrator问题修复</strong>： 昨日SSH Orchestrator出现运行失败的问题，现已修复，并计划在QA测试成功后进行到Orchestrator的迁移。</p></li><li><p><strong>开发环境</strong>： 分享了基于Noah的集中式版本开发环境，该环境运行在Ubuntu上，表现良好。</p></li><li><p><strong>Orchestrator功能改进</strong>：</p><ul><li>讨论了暂停和恢复命令处理器的执行，以优化性能。</li><li>讨论了错误处理，建议在权重方法中仅用于操作进度。</li></ul></li><li><p><strong>CLI模块</strong>：</p><ul><li>讨论了CLI模块的改进，包括添加<code>--weight=false</code>参数，使CLI返回立即，以及优化CLI命令的输出格式。</li></ul></li><li><p><strong>其他议题</strong>：</p><ul><li><strong>Tipsy</strong>： 修改以提供TLS双向认证，并进行删除测试。</li><li><strong>DeepSea</strong>： 启用DeepSea Orchestrator模块，并在开发环境中配置，解决了DeepSea部署问题。</li></ul></li></ol><p>会议决定：</p><ol><li>完成SSH Orchestrator到Orchestrator的迁移。</li><li>优化Orchestrator功能。</li><li>优化CLI模块。</li><li>完成Tipsy和DeepSea的改进。</li></ol><p>会议中提到了SSH Orchestrator、CLI、Tipsy、DeepSea等关键术语，并讨论了涉及Orchestrator改进和CLI模块优化的多个议题。</p>",5)])])}const S=e(i,[["render",a]]);export{g as __pageData,S as default};
